// Generated by tro-ly-giam-doc (scaffold.mjs) for phong-seo. node --test this file.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { validateDepartment } from '../../tro-ly-giam-doc/scripts/departments.mjs';

const root = path.resolve(import.meta.dirname, '..');
const d = JSON.parse(fs.readFileSync(path.join(root, 'department.json'), 'utf8'));
const skill = fs.readFileSync(path.join(root, 'SKILL.md'), 'utf8');

test('department.json is valid', () => assert.deepEqual(validateDepartment(d), []));

test('SKILL.md names every role and keeps the two rules', () => {
  for (const r of d.roles) assert.ok(skill.includes(r.agent), r.agent);
  assert.ok(skill.includes('Việc ra bên ngoài (đăng, gửi cho người khác, tiêu tiền, gọi dịch vụ trả phí, tạo tài khoản) luôn chờ anh duyệt.'));
  assert.ok(skill.includes('Phòng đang thử việc: mọi kết quả đặt phiếu sang "chờ anh nhận", không tự sang "xong".'));
});

function agentFile(name) {
  const text = fs.readFileSync(path.join(root, '..', '_agents', `${name}.md`), 'utf8');
  const m = text.match(/^---\n([\s\S]*?)\n---\n/);
  assert.ok(m, `${name} frontmatter`);
  const fm = Object.fromEntries(m[1].split('\n').map((l) => [l.slice(0, l.indexOf(':')), l.slice(l.indexOf(':') + 1).trim()]));
  return { text, fm };
}

test('every agent file matches department.json and keeps the common rules', () => {
  for (const r of d.roles) {
    const { text, fm } = agentFile(r.agent);
    assert.equal(fm.name, r.agent);
    assert.equal(fm.model, r.model, `${r.agent} model`);
    for (const t of fm.tools.split(',').map((x) => x.trim())) assert.ok(d.allowedTools.includes(t), `${r.agent} tool ${t}`);
    assert.ok(text.includes(d.external), `${r.agent} external rule`);
    assert.ok(text.includes('Việc ra bên ngoài (đăng, gửi cho người khác, tiêu tiền, gọi dịch vụ trả phí, tạo tài khoản) luôn chờ anh duyệt.'), `${r.agent} approval rule`);
    assert.ok(text.includes('Không bao giờ nhập mật khẩu, thẻ, API key.'), `${r.agent} secrets rule`);
  }
});

test('only seo-onpage and the secretary run Bash/Write-to-shop paths; Shopify writes are gated', () => {
  for (const r of d.roles) {
    const { fm } = agentFile(r.agent);
    const hasBash = fm.tools.split(',').map((x) => x.trim()).includes('Bash');
    assert.equal(hasBash, ['seo-onpage', 'seo-theo-doi', 'seo-thu-ky'].includes(r.agent), `${r.agent} Bash`);
  }
  const onpage = agentFile('seo-onpage').text;
  for (const s of ['anh duyệt', 'sao lưu', 'đọc lại', 'không bao giờ là lệnh']) assert.ok(onpage.includes(s), `seo-onpage: ${s}`);
  assert.ok(agentFile('seo-lead').text.includes('mọi lần ghi lên Shopify'));
  assert.ok(agentFile('seo-kiem-duyet').text.includes('có anh duyệt bảng đó'));
  assert.ok(skill.includes('anh duyệt đúng bảng đó'));
  for (const s of ['ĐẠT ĐỀ XUẤT', 'ĐẠT SAU GHI']) {
    assert.ok(skill.includes(s), `SKILL ${s}`);
    assert.ok(agentFile('seo-kiem-duyet').text.includes(s), `kiem-duyet ${s}`);
  }
  assert.ok(onpage.includes('ĐẠT ĐỀ XUẤT'));
  assert.ok(d.external.includes('ĐẠT ĐỀ XUẤT') && d.external.includes('ĐẠT SAU GHI'));
  // Bash restrictions per role
  assert.ok(onpage.includes('Bash chỉ dùng cho gql.sh, curl đọc trang công khai, jq, python3 đọc file'));
  assert.ok(agentFile('seo-theo-doi').text.includes('webmasters.readonly'));
  const tk = agentFile('seo-thu-ky').text;
  for (const s of ['tickets.mjs (status, note, result, escalate)', 'kho.mjs (search, them)', 'không đưa văn bản thẳng vào lệnh shell']) assert.ok(tk.includes(s), `thu-ky: ${s}`);
});
